(()=>{
'use strict';
const CATALOG=window.GDA_CATALOG||[], LESSONS=window.GDA_LESSONS||{}, BANK=window.GDA_INTERVIEW_BANK?.questions||[];
const STORAGE='gda-v1-learning-archive';
const time=()=>new Date().toISOString();
const DAY=86400000;
const baseState=()=>({schema:1,createdAt:time(),updatedAt:time(),lastLesson:'CPP-01',quizzes:{},coding:{},deep:{},reviews:{},mentor:{},interview:{},settings:{runnerToken:''}});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>d?new Date(d).toLocaleDateString('zh-CN',{month:'short',day:'numeric'}):'—';
const todayTs=()=>new Date().setHours(0,0,0,0);
function load(){try{let s=JSON.parse(localStorage.getItem(STORAGE)||'null');if(s&&s.schema===1&&s.quizzes&&s.coding&&s.reviews)return {...baseState(),...s};}catch(e){console.warn('无法读取存档',e)}return baseState()}
let data=load(),route='home',activeQuizReset=new Set(),activeReviewId=null,reviewFilter='due',sidebarExpanded=window.innerWidth>800,tab='all',isSaving=false;
function save(){data.updatedAt=time();try{localStorage.setItem(STORAGE,JSON.stringify(data));setSaveStatus('已自动保存')}catch(e){setSaveStatus('保存失败，请导出备份')}}
function setSaveStatus(text){const s=document.getElementById('save-status');if(s)s.textContent=text;}
const ico=(name,size=18)=>{let icons={
 book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/>',
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V10Z"/><path d="M9 21v-8h6v8"/>',
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 chart:'<path d="M3 3v18h18"/><path d="M7 16v-4M12 16V8M17 16V5"/>',
 repeat:'<path d="m17 2 4 4-4 4"/><path d="M3 11V9a3 3 0 0 1 3-3h15"/><path d="m7 22-4-4 4-4"/><path d="M21 13v2a3 3 0 0 1-3 3H3"/>',
 settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2 2-.2-.1a1.7 1.7 0 0 0-1.8-.3 1.7 1.7 0 0 0-1 1.5V21h-3v-.3a1.7 1.7 0 0 0-1-1.5 1.7 1.7 0 0 0-1.8.3l-.2.1-2-2 .1-.1a1.7 1.7 0 0 0 .3-1.8 1.7 1.7 0 0 0-1.6-1H5v-3h.3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.8l-.1-.2 2-2 .2.2a1.7 1.7 0 0 0 1.8.3 1.7 1.7 0 0 0 1-1.6V5h3v.3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.8-.3l.2-.2 2 2-.1.2a1.7 1.7 0 0 0-.3 1.8 1.7 1.7 0 0 0 1.6 1h.3v3h-.3a1.7 1.7 0 0 0-1.3.6Z"/>',
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',left:'<path d="m15 18-6-6 6-6"/>',right:'<path d="m9 18 6-6-6-6"/>',
 check:'<path d="m20 6-11 11-5-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 code:'<path d="m8 8-4 4 4 4m8-8 4 4-4 4m-3-12-2 16"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v3h16v-3"/>',
 upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v3h16v-3"/>',
 file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',
 light:'<path d="M9 18h6m-6 4h6M8.5 14.5a6 6 0 1 1 7 0L15 18H9l-.5-3.5Z"/>',
 external:'<path d="M13 5h6v6m0-6-9 9"/><path d="M19 13v6H5V5h6"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
 play:'<path d="m8 5 11 7-11 7V5Z"/>',
 target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
 spark:'<path d="m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3L12 3Z"/>',
 copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',
 search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',
 menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',
 alert:'<path d="M10.3 4.3 2 19a1 1 0 0 0 .9 1.5H21a1 1 0 0 0 .9-1.5L13.7 4.3a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4m0 4h.01"/>',
 save:'<path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2Z"/><path d="M17 21v-8H7v8M7 3v6h8"/>'};
 return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.info}</svg>`;};
const countAnswered=(id)=>{let l=LESSONS[id];return l?l.quizzes.filter(q=>data.quizzes[q.id]?.attempts?.length).length:0};
const codeDone=(id)=>!!data.coding[LESSONS[id]?.coding.id]?.runner?.verified;
const deepDone=id=>!!data.deep[id]?.submittedAt;
const percent=id=>{const l=LESSONS[id];return l?Math.round(100*(countAnswered(id)+Number(!!data.coding[l.coding.id]?.code?.trim())+Number(deepDone(id)))/(l.quizzes.length+2)):0};
const dueReviews=()=>Object.values(data.reviews).filter(r=>r.dueAt<=Date.now()&&r.status!=='archived');
function readHash(){let raw=decodeURIComponent(location.hash.replace(/^#\/?/,''));route=raw||'home';}
function nav(to){if(window.innerWidth<=800)sidebarExpanded=false;location.hash=to;}
function toast(msg){let el=document.getElementById('toast');if(!el)return;el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200)}
function topHeader(label,context='学习平台'){return `<header class="topbar"><button class="icon-btn mobile-menu" data-action="toggle-sidebar">${ico('menu')}</button><div class="breadcrumb"><span>${esc(context)}</span>${ico('right',14)}<strong>${esc(label)}</strong></div><div class="topbar-actions"><span class="saved-indicator"><span class="save-dot"></span><span id="save-status">本地自动保存</span></span><button class="icon-btn" title="导出备份" data-action="export-backup">${ico('download',18)}</button></div></header>`;}
function sidebar(){let current=route.includes('lesson/')?route.split('/').pop():'';return `<aside class="sidebar ${sidebarExpanded?'':'sidebar-hidden'}" id="sidebar"><div class="brand"><span class="brand-mark">{ }</span><div><div class="brand-title">GameDev Academy</div><div class="brand-subtitle">游戏客户端成长计划</div></div></div><div class="workspace-pill"><span class="workspace-square">G</span><div><b>个人学习空间</b><small>本地离线版 · MVP</small></div>${ico('check',15)}</div><div class="nav-label">工作台</div><nav class="nav"><a href="#home" class="nav-link ${route==='home'?'selected':''}">${ico('home')}<span>学习首页</span></a><a href="#library" class="nav-link ${route==='library'?'selected':''}">${ico('grid')}<span>全部课程</span><span class="nav-counter">125</span></a><a href="#interview" class="nav-link ${route==='interview'?'selected':''}">${ico('target')}<span>面试挑战库</span><span class="nav-counter">${BANK.length}</span></a><a href="#review" class="nav-link ${route==='review'?'selected':''}">${ico('repeat')}<span>复习中心</span>${dueReviews().length?`<span class="review-count">${dueReviews().length}</span>`:''}</a><a href="#stats" class="nav-link ${route==='stats'?'selected':''}">${ico('chart')}<span>学习档案</span></a></nav><div class="nav-label course-label">当前主修 · C++</div><nav class="nav lesson-nav">${CATALOG[0].lessons.map((l,i)=>`<a href="${i<2?'#lesson/'+l.id:'#library'}" class="nav-link lesson-link ${current===l.id?'selected':''} ${i>=2?'muted':''}" title="${esc(l.title)}"><span class="lesson-index">${String(i+1).padStart(2,'0')}</span><span class="lesson-text">${i===0?'代码如何变成程序':i===1?'变量、血量与边界':esc(l.title.split('；')[0])}</span>${i<2?data.mentor[l.id]?.nextLessonApproved?ico('check',14):'':ico('clock',13)}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-tip"><div class="tip-head">${ico('light',17)} 学习策略</div><p>先理解原理，再独立编码。把错误留给错题本，把难题留给导师。</p></div><a href="#settings" class="nav-link ${route==='settings'?'selected':''}">${ico('settings')}<span>设置与备份</span></a></div></aside>`;}
function globalLayout(page,label,context='我的课程'){return `<div class="shell">${sidebar()}<div class="main-wrap">${topHeader(label,context)}<main class="main-content" id="main-content">${page}</main></div></div><div class="toast" id="toast" role="status"></div>`;}
function lessonStatus(id){let l=LESSONS[id];if(!l)return '规划中';if(data.mentor[id]?.nextLessonApproved)return '导师已确认';if(deepDone(id))return '待导师反馈';if(countAnswered(id)||data.coding[l.coding.id]?.code)return '学习中';return '未开始'}
function renderHome(){const total=Object.values(data.quizzes).filter(q=>q.attempts?.length).length, wrong=Object.values(data.reviews).filter(r=>r.kind==='mistake').length, reviewed=Object.values(data.reviews).filter(r=>r.history?.length).length;return globalLayout(`<div class="page-content home-page"><div class="welcome-top"><span class="eyebrow">YOUR LEARNING PATH · 2026</span><span class="micro-note">课程规划版本 V2.3</span></div><section class="hero"><div class="hero-copy"><div class="hero-kicker">${ico('spark',17)} 从概念到真正的工程能力</div><h1>把原理，<em>变成实力。</em></h1><p>不是记住多少概念，而是面对陌生的游戏需求，能独立编码、解释边界、比较方案并验证结果。</p><div class="hero-actions"><button class="btn btn-dark" data-action="go-lesson" data-id="${data.lastLesson in LESSONS?data.lastLesson:'CPP-01'}">${ico('play',16)} 继续学习 ${esc((data.lastLesson||'CPP-01').replace('CPP-','第'))} 课</button><button class="btn btn-soft" data-action="go-review">${ico('repeat',16)} 今日复习 ${dueReviews().length?`<b>${dueReviews().length}</b>`:''}</button></div></div><div class="hero-art"><div class="orbit orbit-1"></div><div class="orbit orbit-2"></div><div class="art-card art-card-top"><span class="tiny-code">C++ / GAME DEV</span><div class="art-code">int <span>main</span>() {<br>&nbsp;&nbsp;learn();<br>&nbsp;&nbsp;<b>build();</b><br>}</div></div><div class="float-symbol s1">&lt;/&gt;</div><div class="float-symbol s2">++</div><div class="art-caption">PRACTICE → REASON → BUILD</div></div></section><div class="section-title-row"><div><span class="eyebrow">OVERVIEW</span><h2>你的学习概览</h2></div><span class="muted-caption">仅记录真实操作，不推算虚假掌握分</span></div><div class="stat-grid"><div class="stat-card"><div class="stat-title">课程总规划 ${ico('book',17)}</div><div class="stat-value">125<span>单元</span></div><div class="stat-foot">11 个模块 · 10门主课 + 面试训练</div></div><div class="stat-card"><div class="stat-title">当前开放 ${ico('code',17)}</div><div class="stat-value">02<span>节课</span></div><div class="stat-foot">C++ 前两课 · 按零基础起步</div></div><div class="stat-card"><div class="stat-title">已完成 A 类题 ${ico('check',17)}</div><div class="stat-value">${String(total).padStart(2,'0')}<span>道题</span></div><div class="stat-foot">${wrong} 个错题知识点 · ${reviewed} 个已开始复习</div></div></div><div class="two-column"><section class="panel continuing"><div class="panel-heading"><div><span class="eyebrow">CONTINUE LEARNING</span><h2>当前学习主线</h2></div><span class="pill green">${esc(lessonStatus(data.lastLesson))}</span></div><div class="continue-banner"><div class="cpp-stamp">C<span>++</span></div><div><span class="muted-caption">C++ 语言与内存模型</span><h3>${esc((LESSONS[data.lastLesson]||LESSONS['CPP-01']).title)}</h3><p>${esc((LESSONS[data.lastLesson]||LESSONS['CPP-01']).subtitle)}</p></div></div><div class="progress-header"><span>本课操作进度 <small>（非掌握评分）</small></span><b>${percent(data.lastLesson)}%</b></div><div class="progress-track"><span style="width:${percent(data.lastLesson)}%"></span></div><button class="btn btn-line full" data-action="go-lesson" data-id="${data.lastLesson}">进入课程 ${ico('arrow',16)}</button></section><section class="panel review-panel"><div class="panel-heading"><div><span class="eyebrow">REVIEW ROUTINE</span><h2>今天的复习任务</h2></div>${ico('repeat',19)}</div><div class="review-hero-num">${dueReviews().length}<span>项待处理</span></div><div class="review-list-mini"><div>${ico('alert',16)} 错题回顾 <b>${dueReviews().filter(r=>r.kind==='mistake').length}</b></div><div>${ico('target',16)} 需求变更 <b>${dueReviews().filter(r=>r.kind==='change').length}</b></div></div><p class="soft-note">先判断原理是否真正掌握，再尝试新的需求约束；复习不阻塞课程主线。</p><button class="btn btn-line full" data-action="go-review">打开复习中心 ${ico('arrow',16)}</button></section></div><div class="section-title-row pad-top"><div><span class="eyebrow">THE CURRICULUM</span><h2>专业能力地图</h2></div><button class="text-link" data-action="go-library">查看全部125课 ${ico('right',15)}</button></div><div class="subject-strip">${CATALOG.slice(0,5).map((c,i)=>`<div class="subject-chip"><div class="subject-symbol">${['{ }','[ ]','C#','U','OS'][i]}</div><div><b>${esc(c.name)}</b><small>${c.count} 课 · ${i===0?'当前主修':'规划中'}</small></div></div>`).join('')}</div><div class="home-footer">本站是本地学习原型 · 答案自动保存在当前浏览器 · 请定期导出备份</div></div>`,'学习首页','个人学习空间');}
function progressCards(l){return `<div class="lesson-progress"><div><b>${countAnswered(l.id)} / ${l.quizzes.length}</b><span>A 类理解题</span></div><div><b>${data.coding[l.coding.id]?.runner?.verified?'已验证':data.coding[l.coding.id]?.code?.trim()?'有草稿':'未开始'}</b><span>B 类编码</span></div><div><b>${deepDone(l.id)?'已提交':'待作答'}</b><span>C 类深度题</span></div></div>`;}
function blockRender(b){switch(b.type){case'prose':return `<div class="lesson-prose">${b.html}</div>`;case'callout':return `<div class="callout ${b.tone||'note'}"><div class="callout-icon">${ico(b.tone==='warning'?'alert':b.tone==='insight'?'light':'info',18)}</div><div><b>${esc(b.title)}</b><p>${b.html}</p></div></div>`;case'code':return `<div class="code-sample"><div class="code-top"><span class="code-dots"><i></i><i></i><i></i></span><span>${esc(b.label)}</span><button data-action="copy-snippet" data-code="${encodeURIComponent(b.code)}" title="复制代码">${ico('copy',14)} 复制</button></div><pre><code>${syntax(b.code,b.lang)}</code></pre></div>`;case'flow':return `<div class="flowchart">${b.nodes.map((x,i)=>`<div class="flow-node"><b>${esc(x.label)}</b><small>${esc(x.desc)}</small></div>${i<b.nodes.length-1?`<div class="flow-arrow">${ico('right',18)}</div>`:''}`).join('')}</div>`;case'compare':return `<div class="compare-grid"><div class="compare-card"><span class="compare-mark">A</span><h4>${esc(b.left.title)}</h4><p>${esc(b.left.body)}</p></div><div class="compare-card"><span class="compare-mark">B</span><h4>${esc(b.right.title)}</h4><p>${esc(b.right.body)}</p></div></div>`;case'steps':return `<div class="steps">${b.items.map((item,i)=>`<div class="step"><div class="step-no">${String(i+1).padStart(2,'0')}</div><div><b>${esc(item.title)}</b><p>${esc(item.desc)}</p></div></div>`).join('')}</div>`;default:return '';}}
function syntax(code,lang){let e=esc(code);if(lang==='bash')return e.replace(/(#[^\n]*)/g,'<span class="tok-comment">$1</span>');return e.replace(/(\b(?:int|double|bool|const|return|if|true|false|void)\b|&lt;iostream&gt;|\b(?:std::cout|std::endl)\b|"[^"\n]*"|\/\/[^\n]*)/g,m=>m.startsWith('//')?`<span class="tok-comment">${m}</span>`:m.startsWith('"')?`<span class="tok-string">${m}</span>`:`<span class="tok-keyword">${m}</span>`);}
function quizHTML(q,i){const history=data.quizzes[q.id]?.attempts||[],attempt=history.at(-1),show=!!attempt&&!activeQuizReset.has(q.id);return `<div class="quiz-card" id="${esc(q.id)}"><div class="quiz-top"><span class="question-index">A${String(i+1).padStart(2,'0')}</span><span class="question-type">即时选择 · 自动判定</span>${history.length?`<span class="answer-history">已作答 ${history.length} 次</span>`:''}</div><h4>${esc(q.prompt)}</h4><div class="quiz-options">${q.choices.map((s,n)=>`<button class="quiz-option ${show?(n===q.correct?'correct':n===attempt.choice?'incorrect':'dimmed'):''}" data-action="answer-quiz" data-qid="${q.id}" data-choice="${n}" ${show?'disabled':''}><span class="option-letter">${'ABCD'[n]}</span><span>${esc(s)}</span>${show&&n===q.correct?ico('check',17):''}</button>`).join('')}</div>${show?`<div class="quiz-feedback ${attempt.correct?'ok':'bad'}">${ico(attempt.correct?'check':'info',17)} <div><b>${attempt.correct?'回答正确':'本题需要复习'}</b><p>${esc(q.explain)}</p>${!attempt.correct?'<small>已加入错题本，会在复习中心出现变式题。</small>':''}</div></div><button class="subtle-btn" data-action="redo-quiz" data-qid="${q.id}">再次练习（保留历史） ${ico('repeat',13)}</button>`:''}</div>`;}
function codeEditor(l){let task=l.coding,draft=data.coding[task.id]||{},code=draft.code??task.starter;let staticReport=draft.staticReport,runner=draft.runner;return `<div class="exercise-card" id="coding"><div class="exercise-head"><div><div class="eyebrow">B · CODING LAB</div><h3>${esc(task.title)}</h3></div><span class="pill amber">C++17 · 实践题</span></div><p class="exercise-description">${esc(task.description)}</p><div class="criteria"><b>验收标准</b><div>${task.checks.map(c=>`<span>${ico('check',14)}${esc(c)}</span>`).join('')}</div></div><div class="editor"><div class="editor-top"><div><span class="editor-circle"></span><span>solution.cpp</span><span class="lang-label">C++17</span></div><span class="editor-badge">${ico('save',13)} 自动保存</span></div><div class="editor-body"><div class="line-gutter" id="line-gutter">${Array.from({length:Math.max(8,code.split('\n').length)},(_,i)=>i+1).join('<br>')}</div><textarea spellcheck="false" class="code-textarea" id="code-input" data-code-id="${task.id}" aria-label="C++ 代码编辑器">${esc(code)}</textarea></div><div class="editor-toolbar"><span class="helper">Tab 缩进 · 独立编写 · 可随时修改</span><div><button class="btn btn-quiet" data-action="reset-code" data-code-id="${task.id}">${ico('repeat',14)} 重置</button><button class="btn btn-secondary" data-action="static-check" data-code-id="${task.id}">${ico('search',14)} 结构检查</button><button class="btn btn-dark" data-action="run-code" data-code-id="${task.id}">${ico('play',14)} 真实运行</button></div></div></div><div class="code-status"><div class="status-label">${ico('info',16)} <b>验证状态</b></div><div class="status-pills"><span class="pill ${staticReport?'green':'neutral'}">${staticReport?'已做结构检查':'未检查结构'}</span><span class="pill ${runner?.verified?'green':'amber'}">${runner?.verified?'沙箱真实测试通过':'尚未真实编译验证'}</span></div><p>结构检查只根据代码文本给出提示，<strong>不等于真实编译或自动判题通过</strong>。真实运行需启动可选的 Docker 隔离判题器。也可以复制代码到 OnlineGDB 验证。</p></div>${staticReport?`<div class="diagnostics"><b>静态结构检查（非编译）</b><ul>${staticReport.items.map(x=>`<li class="${x.ok?'pass':'warn'}">${ico(x.ok?'check':'alert',15)}${esc(x.text)}</li>`).join('')}</ul><p>${esc(staticReport.note)}</p></div>`:''}${runner?`<div class="runner-result"><b>${runner.verified?'真实沙箱测试通过':runner.error?'运行失败':'运行结果'}</b><pre>${esc(runner.output||runner.error||'无输出')}</pre><small>执行环境：${esc(runner.environment||'本地 Docker 判题器')} · ${esc(runner.at||'')}</small></div>`:''}<div class="sample-block"><div class="sample-head">${ico('target',16)} 测试样例 <span>公开样例（仅供自查）</span></div>${task.sample.map(t=>`<div class="test-row"><div><small>输入 / 调用</small><code>${esc(t.input)}</code></div><div><small>期望输出</small><code>${esc(t.output)}</code></div></div>`).join('')}</div><details class="hint-details"><summary>${ico('light',17)} 需要提示？按需展开（避免提前看答案）</summary><ol>${task.hints.map(h=>`<li>${esc(h)}</li>`).join('')}</ol></details><div class="external-help"><div><b>没有 Docker？</b><p>可复制代码到在线编译器，在那里运行并把结果记录回来；网站不会把手动输入的日志伪装成自动验证。</p></div><button class="btn btn-line" data-action="copy-open-code">复制并打开 OnlineGDB ${ico('external',14)}</button></div><div class="manual-proof"><label for="manual-evidence">外部编译证据（可选：粘贴编译器版本、日志和测试输出）</label><textarea id="manual-evidence" data-proof-id="${task.id}" placeholder="例如：本地 g++ --version... / 编译命令 / 实际输出...">${esc(draft.evidence||'')}</textarea><span>这份证据会随学习回执交给导师核查，未自动计为“测试通过”。</span></div></div>`;}
function deepHTML(l){let d=data.deep[l.id]||{},answers=d.answers||{};return `<div class="exercise-card deep-card" id="deep"><div class="exercise-head"><div><div class="eyebrow">C · DEEP REASONING</div><h3>${esc(l.deep.title)}</h3></div><span class="pill purple">导师深度批改</span></div><p class="exercise-description">先独立思考。这里没有即时标准答案；重点是你能否解释原理、取舍、边界和扩展。全部答案自动保存，课末一次导出给导师。</p>${l.deep.questions.map((q,i)=>`<div class="deep-question"><div class="deep-title"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(q.label)}</b>${i===2?'<span class="mini-tag">需求变化</span>':''}</div><p>${esc(q.prompt)}</p><textarea rows="5" data-deep-lesson="${l.id}" data-deep-field="${q.id}" placeholder="${esc(q.placeholder)}">${esc(answers[q.id]||'')}</textarea></div>`).join('')}<div class="submit-strip"><div><b>${d.submittedAt?'本课已提交回执':'完成后只需提交一次'}</b><p>${d.submittedAt?'提交时间：'+fmt(d.submittedAt)+'；修改答案后可再次导出新版回执':'A类题本地判定、B类代码和C类答案统一生成报告，不逐题发送给AI。'}</p></div><button class="btn btn-dark" data-action="submit-lesson" data-id="${l.id}">${ico('file',16)} ${d.submittedAt?'重新导出回执':'完成本课并导出回执'}</button></div></div>`;}
function lessonContent(id){let l=LESSONS[id];if(!l)return renderLibrary();data.lastLesson=id;save();let index=CATALOG[0].lessons.findIndex(x=>x.id===id);let next=Object.keys(LESSONS)[index+1];return globalLayout(`<div class="lesson-page"><div class="lesson-article"><div class="lesson-back"><button data-action="go-library">${ico('left',15)} 全部课程</button><span>/</span><span>C++ 语言与内存模型</span></div><div class="lesson-intro"><span class="eyebrow">LESSON ${esc(id)}</span><h1>${esc(l.title)}</h1><p class="lesson-subtitle">${esc(l.subtitle)}</p><div class="lesson-meta"><span>${ico('clock',15)} ${esc(l.duration)}</span><span>${ico('target',15)} ${esc(l.level)}</span><span>${ico('file',15)} 内容版本 ${esc(l.version)}</span></div><button class="ask-tutor-btn" data-action="ask-tutor" data-id="${l.id}">${ico('light',16)} 学习中遇到问题？带上本课上下文问导师 ${ico('external',14)}</button></div>${progressCards(l)}<div class="lesson-section" id="objectives"><div class="section-num">LEARNING OBJECTIVES</div><h2>完成这节课，你应该能够</h2><div class="goal-grid">${l.objectives.map((o,i)=>`<div class="goal"><span>${ico('check',14)}</span>${esc(o)}</div>`).join('')}</div><p class="lead-prose">${esc(l.overview)}</p></div>${l.sections.map(s=>`<section class="lesson-section" id="${esc(s.id)}"><div class="section-num">${esc(s.id.toUpperCase())}</div><h2>${esc(s.title)}</h2>${s.blocks.map(blockRender).join('')}</section>`).join('')}<section class="lesson-section practice-intro" id="quiz"><div class="section-num">INTERACTIVE PRACTICE</div><h2>把知识变成可验证的理解</h2><p class="lead-prose">下面的练习分成 A / B / C 三类：简单判断立即揭晓，代码在编辑区独立完成，深度思考留到课终统一提交。</p><div class="practice-types"><div><span class="type-dot type-a">A</span><b>即时反馈</b><small>不用发消息</small></div><div><span class="type-dot type-b">B</span><b>独立编码</b><small>记录真实证据</small></div><div><span class="type-dot type-c">C</span><b>技术思辨</b><small>课末集中批改</small></div></div></section><section class="lesson-section quiz-section"><div class="section-num">A · INSTANT FEEDBACK</div><h2>随堂理解练习</h2><p class="section-caption">每题即时反馈，并保留首次作答与复习记录。</p>${l.quizzes.map(quizHTML).join('')}</section><section class="lesson-section">${codeEditor(l)}</section><section class="lesson-section">${deepHTML(l)}</section><div class="lesson-next"><div><span class="eyebrow">WHAT'S NEXT</span><h3>把今天的知识带到下一课</h3><p>别急着追求课数。先独立完成练习、导出学习回执，再根据导师反馈决定下一步。</p></div><button class="btn btn-line" data-action="go-lesson" data-id="${next||'CPP-01'}">${next?'预览下一课':'返回第1课'} ${ico('arrow',15)}</button></div></div><aside class="toc"><div class="toc-sticky"><div class="toc-title">本课目录</div><a href="#objectives" data-anchor="objectives">学习目标</a>${l.sections.map(s=>`<a href="#${s.id}" data-anchor="${s.id}">${esc(s.title)}</a>`).join('')}<a href="#quiz" data-anchor="quiz">A · 即时理解</a><a href="#coding" data-anchor="coding">B · 代码练习</a><a href="#deep" data-anchor="deep">C · 深度作答</a><div class="toc-divider"></div><div class="toc-title">知识标签</div><div class="toc-tags">${l.tags.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="toc-cta">${ico('info',16)} 学会的标准不是阅读完成，而是能独立实现并解释选择。</div></div></aside></div>` ,l.title,'C++ · '+id);}
function reviewHTML(){const reviews=Object.values(data.reviews).filter(r=>reviewFilter==='all'||(reviewFilter==='due'&&r.dueAt<=Date.now())||(reviewFilter==='mistake'&&r.kind==='mistake')||(reviewFilter==='change'&&r.kind==='change')).sort((a,b)=>a.dueAt-b.dueAt);return globalLayout(`<div class="page-content"><div class="page-heading"><div><span class="eyebrow">REVIEW SYSTEM</span><h1>复习不是重复做题，<br><em>而是重新学会思考。</em></h1><p>错题回顾 + 需求变更练习。保留首次答案、错误原因和复习证据，检验知识能否迁移到新的游戏约束中。</p></div><div class="heading-art">${ico('repeat',54)}</div></div><div class="review-stats"><div><span>今天到期</span><b>${dueReviews().length}</b></div><div><span>错题记录</span><b>${Object.values(data.reviews).filter(r=>r.kind==='mistake').length}</b></div><div><span>需求变化</span><b>${Object.values(data.reviews).filter(r=>r.kind==='change').length}</b></div><div><span>累计复习</span><b>${Object.values(data.reviews).reduce((a,r)=>a+(r.history?.length||0),0)}</b></div></div><div class="section-title-row"><div><h2>复习任务</h2><p class="muted-caption">答错之后进入复习；完成C类提交后自动生成迁移任务。</p></div><div class="segmented">${[['due','今日到期'],['mistake','错题'],['change','需求变更'],['all','全部']].map(([v,t])=>`<button class="${reviewFilter===v?'on':''}" data-action="review-filter" data-value="${v}">${t}</button>`).join('')}</div></div><div class="review-items">${reviews.length?reviews.map(reviewCard).join(''):`<div class="empty-state">${ico('check',32)}<h3>这里暂时没有待复习内容</h3><p>完成 A 类题或提交一节课程后，系统会自动生成错题和需求变化复习卡。</p><button class="btn btn-dark" data-action="go-lesson" data-id="CPP-01">去学习第1课 ${ico('arrow',15)}</button></div>`}</div><div class="review-guide"><h3>复习安排是如何工作的？</h3><p>默认采用当天纠错、1天、3天、7天、14天逐渐延长的复习间隔。答错会重新排入当前待复习队列。需求变更题需要你书写方案，不做虚假的自动语义打分；由你自评并在学习回执中供导师复核。</p></div></div>`,'复习中心','能力巩固');}
function reviewCard(r){let l=LESSONS[r.lessonId],q=l?.quizzes.find(q=>q.id===r.sourceId),v=q?.variant;let open=activeReviewId===r.id;let isDue=r.dueAt<=Date.now();const hist=r.history||[];return `<div class="review-item ${open?'open':''}"><div class="review-item-head"><div class="review-type ${r.kind}">${ico(r.kind==='mistake'?'alert':'repeat',17)}</div><div class="review-item-name"><div><span class="eyebrow">${r.kind==='mistake'?'MISTAKE REVIEW':'TRANSFER CHALLENGE'} · ${esc(r.lessonId)}</span><h3>${r.kind==='mistake'?'错题变式 · '+esc(r.sourceId):'需求变更 · '+esc(l?.title)}</h3></div><p>${r.kind==='mistake'?'重新判断相同知识点的新题，而不是回忆原选项。':'把课堂知识迁移到不同的游戏需求和限制。'}</p></div><span class="pill ${isDue?'amber':'neutral'}">${isDue?'待复习':'下次 '+fmt(r.dueAt)}</span></div>${r.kind==='mistake'?`<div class="wrong-reason-row"><label>错因归类</label><select data-review-reason="${esc(r.id)}">${['待分析','概念不清','审题疏漏','边界遗漏','代码实现错误','方案取舍错误','其他'].map(k=>`<option value="${k}" ${r.wrongReason===k?'selected':''}>${k}</option>`).join('')}</select></div>`:''}<div class="review-foot"><span>已复习 ${hist.length} 次 · 当前复习级别 ${r.level||0}</span><button class="btn btn-line" data-action="open-review" data-rid="${esc(r.id)}">${open?'收起':'开始复习'} ${ico(open?'left':'arrow',14)}</button></div>${open?`<div class="review-open"><p class="review-question">${esc(r.kind==='mistake'?(v?.prompt||q?.prompt||r.prompt):(r.prompt||l?.review.question||''))}</p>${r.kind==='mistake'&&v?`<div class="review-options">${v.choices.map((s,i)=>`<button data-action="review-answer" data-rid="${esc(r.id)}" data-choice="${i}"><span>${'ABCD'[i]}</span>${esc(s)}</button>`).join('')}</div><p class="review-hint">本轮反馈会在作答后显示；原错题首次答案始终保留。</p>`:`<textarea rows="5" id="review-response-${esc(r.id)}" placeholder="描述新约束下的设计、边界和验证方式……">${esc(r.draft||'')}</textarea><div class="review-actions"><button class="btn btn-secondary" data-action="save-review-draft" data-rid="${esc(r.id)}">保存草稿</button><button class="btn btn-dark" data-action="submit-review-change" data-rid="${esc(r.id)}">记录本次迁移作答</button></div><p class="review-hint">主观题没有自动正确率；记录作答后会进入待导师复核状态。</p>`}</div>`:''}</div>`;}
function libraryHTML(){return globalLayout(`<div class="page-content"><div class="page-heading"><div><span class="eyebrow">COURSE LIBRARY · BLUEPRINT V2.2</span><h1>一条主线，<br><em>建立完整的客户端能力体系。</em></h1><p>10 门核心课程 + 贯穿式面试训练。当前只制作了 C++ 前两课的可交互教材，其余仍为真实规划，不冒充已上线课程。</p></div><div class="heading-art">${ico('grid',54)}</div></div><div class="library-toolbar"><span>课程总计 <b>11</b> 门 · <b>125</b> 个课次</span><div class="segmented"><button data-action="library-tab" data-value="all" class="${tab==='all'?'on':''}">全部</button><button data-action="library-tab" data-value="available" class="${tab==='available'?'on':''}">已上线</button></div></div><div class="catalogue-list">${CATALOG.filter(c=>tab==='all'||c.id==='CPP').map((c,ci)=>`<div class="catalogue-card"><div class="catalogue-head"><div class="subject-symbol lg">${['{ }','[ ]','C#','U','OS','NET','∑','ARCH','FPS','GIT','Q&A'][CATALOG.indexOf(c)]}</div><div><span class="eyebrow">MODULE ${String(CATALOG.indexOf(c)+1).padStart(2,'0')}</span><h2>${esc(c.name)}</h2><p>${c.count} 课 ${c.id==='CPP'?'· 已上线 2 课':'· 当前仅有大纲'}</p></div><span class="pill ${c.id==='CPP'?'green':'neutral'}">${c.id==='CPP'?'学习中':'待制作'}</span></div><details ${c.id==='CPP'?'open':''}><summary>查看课次与实践任务 ${ico('right',15)}</summary><div class="catalogue-lessons">${c.lessons.map((l,i)=>`<div class="catalogue-lesson"><span class="catalogue-no">${String(i+1).padStart(2,'0')}</span><div><b>${esc(l.title)}</b><p>${esc(l.practice)}</p></div>${l.id in LESSONS?`<button class="btn btn-small" data-action="go-lesson" data-id="${l.id}">进入课程 ${ico('arrow',13)}</button>`:`<span class="pill neutral">规划中</span>`}</div>`).join('')}</div></details></div>`).join('')}</div></div>`,'全部课程','课程目录');}
function statsHTML(){const ls=Object.values(LESSONS);const quizArr=Object.values(data.quizzes);const mistakes=Object.values(data.reviews).filter(r=>r.kind==='mistake');return globalLayout(`<div class="page-content"><div class="page-heading"><div><span class="eyebrow">LEARNING ARCHIVE</span><h1>每一次思考，<br><em>都有迹可循。</em></h1><p>学习档案只显示有记录的操作和导师正式反馈；读完课程不等于独立掌握。</p></div><div class="heading-art">${ico('chart',54)}</div></div><div class="review-stats"><div><span>已回答 A 题</span><b>${quizArr.filter(q=>q.attempts?.length).length}</b></div><div><span>首次答错</span><b>${quizArr.filter(q=>q.attempts?.[0]&&!q.attempts[0].correct).length}</b></div><div><span>完成 C 题提交</span><b>${ls.filter(l=>deepDone(l.id)).length}</b></div><div><span>导师已确认</span><b>${Object.values(data.mentor).filter(x=>x.nextLessonApproved===true).length}</b></div></div><div class="section-title-row"><div><h2>课程学习记录</h2><p class="muted-caption">内容制作与能力认证分开统计。</p></div></div><div class="archive-table"><div class="archive-head"><span>课程</span><span>理解练习</span><span>编码结果</span><span>导师反馈</span><span>操作</span></div>${ls.map(l=>`<div class="archive-row"><b>${esc(l.id)} · ${esc(l.title)}</b><span>${countAnswered(l.id)}/${l.quizzes.length}</span><span>${codeDone(l.id)?'沙箱已验证':data.coding[l.coding.id]?.code?.trim()?'待真实验证':'未练习'}</span><span>${data.mentor[l.id]?.summary?'已导入':'未评估'}</span><button class="text-link" data-action="export-lesson" data-id="${l.id}">导出回执 ${ico('download',14)}</button></div>`).join('')}</div><div class="section-title-row pad-top"><div><h2>知识薄弱点</h2><p class="muted-caption">根据真实错题记录生成，不会从示例题推断能力。</p></div></div><div class="weak-grid">${mistakes.length?mistakes.map(r=>`<div class="weak-card"><span>${esc(r.lessonId)}</span><b>${esc(r.sourceId)}</b><small>复习次数 ${r.history?.length||0} · 下次 ${fmt(r.dueAt)}</small></div>`).join(''):'<div class="empty-line">暂无实际错题记录。完成 A 类题后会自动生成。</div>'}</div><div class="report-panel"><div>${ico('download',24)}<h3>导出长期学习档案</h3><p>可备份完整历史，也可只导出单课回执交给 ChatGPT 深度批改。</p></div><div><button class="btn btn-line" data-action="export-backup">导出完整 JSON</button><button class="btn btn-dark" data-action="export-lesson" data-id="${data.lastLesson}">导出当前课回执</button></div></div></div>`,'学习档案','个人学习空间');}
function interviewHTML(){
 const done=BANK.filter(q=>!!data.interview?.[q.id]?.submittedAt).length;
 const items=BANK.map(q=>{
  const ready=!!LESSONS[q.lessonId];const h=data.interview?.[q.id]||{};
  return `<article class="interview-card"><div class="interview-head"><span class="eyebrow">${esc(q.id)} · ${esc(q.lessonId)}</span><span class="pill ${ready?'green':'neutral'}">${ready?'可练习':'先学习前置课程'}</span></div>
   <h3>${esc(q.title)}</h3><p class="interview-context">${esc(q.context)}</p>
   <div class="interview-meta"><span>${esc(q.level)}</span><span>${esc(q.source)} · ${esc(q.sourceTopic)}</span><span>题干已审校</span></div>
   ${ready?`<div class="interview-question"><b>基础问题</b><p>${esc(q.question)}</p><b>需求变更</b><p>${esc(q.change)}</p></div><details class="interview-hint"><summary>思路提示（不提供完整答案）</summary><p>${esc(q.hint)}</p></details><label class="interview-label" for="interview-${esc(q.id)}">你的方案 / 代码 / 测试证据</label><textarea id="interview-${esc(q.id)}" rows="5" data-interview-id="${esc(q.id)}" placeholder="先独立分析原理、约束、替代方案、边界和验证方法……">${esc(h.draft||'')}</textarea><div class="interview-actions"><small>${h.submittedAt?'已保存提交记录 · 待导师评估':'自动保存草稿；提交后进入需求变更复习'}</small><button class="btn btn-dark btn-small" data-action="submit-interview" data-id="${esc(q.id)}">${h.submittedAt?'更新提交':'提交挑战'}</button></div>`:`<p class="interview-locked">先完成 ${esc(q.lessonId)} 相关基础知识后再练习。本题保留在题库中，不提前展示参考解答。</p>`}</article>`;
 }).join('');
 return globalLayout(`<div class="page-content"><div class="page-heading"><div><span class="eyebrow">V2.3 · VERIFIED INTERVIEW PROMPTS</span><h1>面试题，<em>不是背答案。</em></h1><p>两份八股只作为选题来源。正式题干经过审校，进阶题按先修课解锁，深度答案留给导师批改而非自动打分。</p></div><div class="heading-art">${ico('target',52)}</div></div><div class="review-stats"><div><span>题库条目</span><b>${BANK.length}</b></div><div><span>已解锁</span><b>${BANK.filter(q=>!!LESSONS[q.lessonId]).length}</b></div><div><span>已提交方案</span><b>${done}</b></div><div><span>来源资料</span><b>2</b></div></div><div class="interview-banner"><div><b>练习流程</b><p>先系统学课 → 再做面试场景题 → 需求变更追问 → 导出评估报告。标为“题干已审校”不表示已经评估你的作答。</p></div><button class="btn btn-line" data-action="export-interviews">导出挑战回执 ${ico('download',14)}</button></div><div class="interview-grid">${items}</div></div>`,'面试挑战库','课程扩展');
}
function submitInterview(id){const q=BANK.find(x=>x.id===id);if(!q||!LESSONS[q.lessonId])return;let a=data.interview?.[id]||{};if(!a.draft?.trim()){toast('请先写出你的分析与方案');return;}a.submittedAt=time();a.history=a.history||[];a.history.push({at:time(),answer:a.draft});data.interview[id]=a;let rid='change:'+id;if(!data.reviews[rid])data.reviews[rid]={id:rid,kind:'change',lessonId:q.lessonId,sourceId:id,prompt:q.change,level:0,status:'pending',dueAt:Date.now()+DAY,history:[],createdAt:time(),draft:''};save();render();toast('挑战已提交，并加入需求变更复习；待导师评估');}
function exportInterviews(){let lines=['# GameDev Academy 面试与需求变更练习回执','',`- 生成时间：${time()}`,'- 题库版本：2.3.0','- 所有方案均待导师人工评估，不以填写文本自动计为掌握',''];for(let q of BANK){let a=data.interview?.[q.id];if(!a?.draft?.trim())continue;lines.push(`## ${q.id} ${q.title}`,`- 对应课次：${q.lessonId}`,`- 来源标签：${q.source} / ${q.sourceTopic}`,`- 提交时间：${a.submittedAt||'尚未提交（仅草稿）'}`,`- 基础问题：${q.question}`,`- 需求变更：${q.change}`,'','### 我的答案',a.draft,'');}download('GameDev-Academy_面试挑战回执_'+new Date().toISOString().slice(0,10)+'.md',lines.join('\n'),'text/markdown;charset=utf-8');toast('面试挑战回执已导出');}

function settingsHTML(){return globalLayout(`<div class="page-content narrow"><div class="page-heading"><div><span class="eyebrow">SYSTEM & DATA</span><h1>设置与备份</h1><p>数据默认保存在当前浏览器的本地存储，关闭页面后通常会保留；清理站点数据、换设备或网址可能丢失，建议定期备份。</p></div></div><div class="settings-box"><h2>数据备份 / 恢复</h2><p>包括课程作答、代码、首次错误、全部复习历史和导师反馈。导入将替换当前记录，请先导出备份。</p><div class="button-row"><button class="btn btn-dark" data-action="export-backup">${ico('download',16)} 导出 JSON 备份</button><button class="btn btn-line" data-action="import-backup">${ico('upload',16)} 导入备份</button><input type="file" id="backup-file" accept=".json,application/json" hidden></div></div><div class="settings-box"><h2>本地 Docker C++ 判题器（可选）</h2><p>网站本身可离线阅读、答题和编辑代码。<strong>真实 C++ 编译</strong>需要另外启动仓库中的隔离执行服务，不能仅凭静态检查宣称通过。</p><label for="runner-token">本地判题器访问令牌</label><div class="runner-token-input"><input type="password" id="runner-token" value="${esc(data.settings.runnerToken||'')}" placeholder="运行 python runner/server.py 后，填写终端显示的令牌"><button class="btn btn-line" data-action="check-runner">检查连接</button></div><p class="small-note">令牌只存于本机浏览器；服务绑定 127.0.0.1:8765，并要求 Docker Desktop 正常运行。不要在这里输入任何网站密码或 API Key。</p><div id="runner-health" class="tiny-status"></div></div><div class="settings-box"><h2>导入导师反馈</h2><p>将我在课程回执批改后输出的结构化 JSON 粘贴在这里。系统会检查课次 ID 与六维分数，再追加到档案；不会改写你之前的答案。</p><textarea id="mentor-json" rows="8" placeholder='{"lessonId":"CPP-01","summary":"...","scores":{"P":3,"I":2,"B":2,"T":3,"E":2,"V":2},"nextLessonApproved":false,"weaknesses":["..."]}'></textarea><button class="btn btn-dark" data-action="import-mentor">${ico('upload',15)} 保存导师反馈</button></div><div class="settings-box"><h2>课程来源与可维护性</h2><p><code>curriculum/curriculum-plan.md</code> 是课程蓝图 V2.2；本网站将教材和答题数据分开。代码见 <code>src/data/lessons.js</code>，课次索引见 <code>src/data/catalog.js</code>，面试题库见 <code>src/data/interview-bank.js</code>。后续添加课程只需要增加内容数据并更新版本号。</p></div></div>`,'设置与备份','个人学习空间');}
function render(){readHash();let body;if(route==='home')body=renderHome();else if(route==='library')body=libraryHTML();else if(route==='interview')body=interviewHTML();else if(route==='review')body=reviewHTML();else if(route==='stats')body=statsHTML();else if(route==='settings')body=settingsHTML();else if(route.startsWith('lesson/'))body=lessonContent(route.split('/')[1]);else body=renderHome();document.getElementById('app').innerHTML=body;document.title=(route.startsWith('lesson/')?(LESSONS[route.split('/')[1]]?.title||'课程'):'GameDev Academy')+' · 游戏客户端学习';}
function download(name,content,type='text/plain;charset=utf-8'){let blob=new Blob([content],{type});let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportBackup(){const s={...data,settings:{...data.settings,runnerToken:''},exportedAt:time(),format:'gda-backup-v1',blueprintVersion:'2.2.0'};download('GameDev-Academy_学习档案_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(s,null,2),'application/json');toast('学习档案备份已导出');}
function findQuiz(qid){for(let l of Object.values(LESSONS)){let q=l.quizzes.find(x=>x.id===qid);if(q)return {q,l};}return null;}
function mistakeReview(q,l){let id='mistake:'+q.id;if(data.reviews[id])return;data.reviews[id]={id,kind:'mistake',lessonId:l.id,sourceId:q.id,level:0,status:'pending',dueAt:Date.now(),createdAt:time(),history:[],wrongReason:'待分析',tags:q.tags||[]};}
function answerQuiz(qid,choice){let f=findQuiz(qid);if(!f)return;let {q,l}=f;let obj=data.quizzes[q.id]||{attempts:[],firstAnswer:null};if(obj.firstAnswer===null)obj.firstAnswer=choice;obj.attempts.push({choice,correct:choice===q.correct,at:time(),questionVersion:l.version});data.quizzes[q.id]=obj;if(choice!==q.correct)mistakeReview(q,l);activeQuizReset.delete(qid);save();render();document.getElementById(qid)?.scrollIntoView({block:'center'});}
function lint(code,id){let items=[];if(id==='CPP-01-B01'){items=[{ok:/#\s*include\s*<iostream>/.test(code),text:'看到 #include <iostream>（文本检查）'},{ok:/\bint\s+main\s*\(\s*(?:void)?\s*\)/.test(code),text:'看到 int main() 程序入口（文本检查）'},{ok:/std\s*::\s*cout\s*<<\s*"Hello, Game!"/.test(code),text:'看到预期的 std::cout 字符串输出语句（文本检查）'},{ok:/return\s+0\s*;/.test(code),text:'看到 return 0;（文本检查）'}];}else{items=[{ok:/\bint\s+ApplyDamage\s*\(\s*int\s+hp\s*,\s*int\s+damage\s*\)/.test(code),text:'函数签名看起来符合题意（文本检查）'},{ok:/\bif\s*\(/.test(code),text:'出现条件分支（文本检查）'},{ok:/\breturn\b/.test(code),text:'出现 return（文本检查）'},{ok:/\bdamage\s*>=\s*hp\b/.test(code)||/\bhp\s*<=\s*damage\b/.test(code),text:'似乎考虑了伤害 ≥ 当前血量的条件（文本检查）'}];}return {items,note:'这是启发式文本检查，可能有误报/漏报。必须使用真实编译器和测试用例验证，或把日志交给导师判断。',at:time()};}
async function copyText(text){try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);return true}}catch(e){}let t=document.createElement('textarea');t.value=text;document.body.appendChild(t);t.select();let r=document.execCommand('copy');t.remove();return r;}
function reportFor(id){let l=LESSONS[id];if(!l)return '';let c=data.coding[l.coding.id]||{},d=data.deep[id]||{},answers=d.answers||{},m=data.mentor[id];let lines=[`# ${id} 学习回执`,``, `- 导出时间：${time()}`,`- 课程：${l.title}`,`- 教材版本：${l.version}`,`- 总蓝图版本：2.3.0`,`- 作答状态：${d.submittedAt?'已点击课末提交':'尚未点击课末提交'}`,`- 导师评分：${m?JSON.stringify(m.scores||{}) :'未评估'}`,``, '## A类 · 即时理解题'];for(let q of l.quizzes){let r=data.quizzes[q.id];lines.push(`### ${q.id} ${q.prompt}`,`- 首次选择：${r?.attempts?.length?q.choices[r.attempts[0].choice]:'未作答'}`,`- 首次判定：${r?.attempts?.length?(r.attempts[0].correct?'正确':'错误'):'未评估'}`,`- 最终选择：${r?.attempts?.length?q.choices[r.attempts.at(-1).choice]:'未作答'}`,`- 尝试次数：${r?.attempts?.length||0}`,`- 关联标签：${q.tags.join('、')}`,'');}lines.push('## B类 · 编程作答',`- 题目：${l.coding.title}`,`- 自动沙箱验证：${c.runner?.verified?'已通过':'未验证通过'}`,`- 最后静态检查：${c.staticReport?.at||'无'}`,`- 最近真实判题：${c.runner?.at||'无'}`,`- 首次提交的代码：${c.firstSubmittedCode?'见下方首次提交代码块':'无'}`,`- 已保存验证尝试：${c.history?.length||0}`,`- 判题环境：${c.runner?.environment||'无'}`,`- 结果详情：${c.runner?.output||c.runner?.error||'无'}`,'','```cpp',c.code??l.coding.starter,'```','','### 外部编译证据',c.evidence||'无','','### 首次提交的代码','```cpp',c.firstSubmittedCode||'（未提交）','```','','### 验证尝试历史',...(c.history||[]).map(h=>'- '+h.at+' / '+h.kind+' / '+(h.result?.verified===true?'沙箱通过':h.result?.verified===false?'未通过或运行失败':'仅静态检查')),'','## C类 · 深度作答');for(let q of l.deep.questions){lines.push(`### ${q.label}：${q.prompt}`,(answers[q.id]||'（未作答）'),'');}lines.push('## 错题与复习历史');let arr=Object.values(data.reviews).filter(r=>r.lessonId===id);for(let r of arr){lines.push(`- ${r.kind} / ${r.sourceId||'需求变更'}：复习 ${r.history?.length||0} 次；错因 ${r.wrongReason||'不适用'}；阶段 ${r.level||0}；下次 ${fmt(r.dueAt)}`);for(let h of (r.history||[])){lines.push(`  - ${h.at}：${h.kind||'作答'} ${h.answer??''} / ${h.correct===undefined?'主观待评估':h.correct?'正确':'错误'}`)}}if(!arr.length)lines.push('暂无记录');for(let q of BANK.filter(q=>q.lessonId===id)){let attempt=data.interview?.[q.id];if(attempt?.draft?.trim())lines.push(`## 关联面试挑战 ${q.id} ${q.title}`,`- 问题：${q.question}`,`- 需求变更：${q.change}`,`- 提交时间：${attempt.submittedAt||'仅草稿'}`,attempt.draft,'');}lines.push('','## 导师反馈',m?JSON.stringify(m,null,2):'尚未导入导师反馈','', '---','本报告记录实际网页行为。静态检查不等于编译；自评不等于导师审核。');return lines.join('\n');}
function exportReport(id){const txt=reportFor(id);download(id+'_学习回执_'+new Date().toISOString().slice(0,10)+'.md',txt,'text/markdown;charset=utf-8');toast('已导出本课学习回执，可上传给 ChatGPT');}
function submitLesson(id){let d=data.deep[id]||{answers:{}};d.submittedAt=time();data.deep[id]=d;let reviewId='change:'+id;if(!data.reviews[reviewId])data.reviews[reviewId]={id:reviewId,kind:'change',lessonId:id,sourceId:null,prompt:LESSONS[id].review.question,level:0,status:'pending',dueAt:Date.now()+DAY,history:[],createdAt:time(),draft:''};save();exportReport(id);render();}
function runStatus(codeId){return data.coding[codeId]||(data.coding[codeId]={history:[]});}
function recordCodeAttempt(c,kind,code,result){c.history=c.history||[];if(!c.firstSubmittedCode)c.firstSubmittedCode=code;c.history.push({kind,at:time(),code,result});if(c.history.length>40)c.history=c.history.slice(-40);}
function codeMistakeReview(l){let id='mistake:'+l.coding.id;if(data.reviews[id])return;data.reviews[id]={id,kind:'mistake',lessonId:l.id,sourceId:l.coding.id,prompt:'这道编程题曾在真实沙箱测试中未通过。请说明失败原因、给出修改策略和至少三个边界测试。',level:0,status:'pending',dueAt:Date.now(),createdAt:time(),history:[],wrongReason:'代码实现错误',tags:['代码实践','边界测试']};}

function markReview(r,correct,answer,kind){r.history=r.history||[];r.history.push({at:time(),kind,answer,correct});if(correct===true){r.level=Math.min(4,(r.level||0)+1);r.dueAt=Date.now()+[1,3,7,14][r.level-1]*DAY;r.status='scheduled';}else if(correct===false){r.level=0;r.dueAt=Date.now();r.status='pending';}else{r.status='pending-mentor';r.dueAt=Date.now()+DAY;r.level=r.level||0;}save();activeReviewId=null;render();toast(correct===null?'已记录迁移题，待导师复核':correct?'本轮已掌握，排入后续复习':'已记录错误，继续加强这个知识点');}
async function checkRunner(){let token=data.settings.runnerToken?.trim();if(!token){toast('请先填入本地判题器令牌');return false;}try{let res=await fetch('http://127.0.0.1:8765/health',{headers:{'X-GDA-Token':token},signal:AbortSignal.timeout(3000)});let json=await res.json();if(!res.ok||!json.ready)throw Error(json.error||json.message||'判题器尚未准备好');document.getElementById('runner-health')&&(document.getElementById('runner-health').textContent='连接成功：'+(json.message||'本地 Docker 判题器已准备好'));toast('已连接本地隔离判题器');return true;}catch(e){let el=document.getElementById('runner-health');if(el)el.textContent='未连接：'+e.message;toast('本地判题器未就绪，请查看 README');return false;}}
async function runCode(id){const lessonId=id.replace(/-B\d{2}$/,'');const l=LESSONS[lessonId];if(!l)return;const c=runStatus(id),code=c.code||l.coding.starter,token=data.settings.runnerToken?.trim();if(!token){toast('请先在“设置与备份”中配置本地 Docker 判题器；也可使用 OnlineGDB 手动验证');return;}toast('正在尝试本地沙箱编译与公开测试……');try{let res=await fetch('http://127.0.0.1:8765/run',{method:'POST',headers:{'Content-Type':'application/json','X-GDA-Token':token},body:JSON.stringify({lessonId,code}),signal:AbortSignal.timeout(26000)});let obj=await res.json();if(!res.ok)throw Error(obj.error||'请求失败');c.runner={verified:!!obj.verified,output:obj.output,error:obj.error,environment:obj.environment||'Docker gcc:14',at:time(),tests:obj.tests||[]};recordCodeAttempt(c,'真实沙箱判题',code,c.runner);if(!c.runner.verified)codeMistakeReview(l);save();render();document.getElementById('coding')?.scrollIntoView({block:'start'});}catch(e){c.runner={verified:false,error:'真实运行未完成：'+e.message,output:'',at:time(),environment:'本机判题器不可用'};save();render();toast('未能执行真实判题。可将代码复制到在线编译器');}}
function handleClick(e){const t=e.target.closest('[data-action]');if(!t)return;const a=t.dataset.action;let id=t.dataset.id;switch(a){case'go-lesson':nav('lesson/'+id);break;case'go-review':nav('review');break;case'submit-interview':submitInterview(id);break;case'export-interviews':exportInterviews();break;case'ask-tutor':{let l=LESSONS[id];if(!l)break;let question=prompt('你在这节课遇到了什么问题？（取消则不发送）');if(!question?.trim())break;let c=data.coding[l.coding.id];const context=`【GameDev Academy 课程内答疑】\n课程 ${id}：${l.title}\n我目前的疑问：${question.trim()}\n当前代码：\n\`\`\`cpp\n${c?.code||'尚未开始B类题'}\n\`\`\`\n请按零基础起点讲清原理、适用边界、技术取舍，并给我一段小测试，不要自动推进下一课。`;copyText(context).then(ok=>{toast(ok?'上下文已复制，请在聊天里粘贴发送':'请手动复制当前问题与代码');if(ok)window.open('https://chatgpt.com/','_blank','noopener,noreferrer');});break;}case'go-library':nav('library');break;case'answer-quiz':answerQuiz(t.dataset.qid,Number(t.dataset.choice));break;case'redo-quiz':activeQuizReset.add(t.dataset.qid);render();document.getElementById(t.dataset.qid)?.scrollIntoView({block:'center'});break;case'static-check':{let c=runStatus(t.dataset.codeId);c.staticReport=lint(c.code??LESSONS[route.split('/')[1]].coding.starter,route.split('/')[1]);recordCodeAttempt(c,'结构检查',c.code??LESSONS[route.split('/')[1]].coding.starter,c.staticReport);save();render();document.getElementById('coding')?.scrollIntoView({block:'start'});break;}case'run-code':runCode(t.dataset.codeId);break;case'copy-open-code':{let l=LESSONS[route.split('/')[1]],c=runStatus(l.coding.id);copyText(c.code??l.coding.starter).then(ok=>{toast(ok?'代码已复制，已打开编译器':'已打开在线编译器，请手动复制代码');window.open('https://www.onlinegdb.com/online_c++_compiler','_blank','noopener,noreferrer');});break;}case'reset-code':{let l=LESSONS[route.split('/')[1]];if(confirm('确定重置当前代码为题目初始模板？历史验证证据仍保留，但草稿会被覆盖。')){let c=runStatus(l.coding.id);c.code=l.coding.starter;c.runner=null;save();render();}break;}case'submit-lesson':submitLesson(id);break;case'export-lesson':exportReport(id);break;case'export-backup':exportBackup();break;case'import-backup':document.getElementById('backup-file')?.click();break;case'copy-snippet':copyText(decodeURIComponent(t.dataset.code)).then(ok=>toast(ok?'已复制代码':'复制失败，请手动选择'));break;case'review-filter':reviewFilter=t.dataset.value;activeReviewId=null;render();break;case'open-review':activeReviewId=activeReviewId===t.dataset.rid?null:t.dataset.rid;render();break;case'review-answer':{let r=data.reviews[t.dataset.rid],f=findQuiz(r.sourceId),v=f?.q.variant;if(v){let choice=Number(t.dataset.choice);markReview(r,choice===v.correct,v.choices[choice],'变式题');}break;}case'save-review-draft':{let r=data.reviews[t.dataset.rid];r.draft=document.getElementById('review-response-'+r.id)?.value||'';save();toast('复习草稿已保存');break;}case'submit-review-change':{let r=data.reviews[t.dataset.rid],ans=document.getElementById('review-response-'+r.id)?.value.trim();if(!ans){toast('请先写出你的需求变化分析');break;}r.draft=ans;markReview(r,null,ans,'需求迁移');break;}case'library-tab':tab=t.dataset.value;render();break;case'check-runner':checkRunner();break;case'import-mentor':importMentor();break;case'toggle-sidebar':sidebarExpanded=!sidebarExpanded;render();break;}}
function importMentor(){let el=document.getElementById('mentor-json');if(!el)return;try{let m=JSON.parse(el.value.trim());if(!LESSONS[m.lessonId])throw Error('课次 ID 不存在');if(typeof m.summary!=='string'||!m.summary.trim())throw Error('缺少 summary');if(typeof m.scores!=='object'||m.scores===null)throw Error('缺少 scores');let scores={};for(let key of ['P','I','B','T','E','V']){const v=m.scores[key];if(v!==null&&(!Number.isInteger(v)||v<0||v>4))throw Error(key+' 必须是 0–4 或 null');scores[key]=v===undefined?null:v;}let allowed={lessonId:m.lessonId,summary:m.summary,scores,weaknesses:Array.isArray(m.weaknesses)?m.weaknesses.filter(x=>typeof x==='string'):[],nextLessonApproved:m.nextLessonApproved===true,importedAt:time()};data.mentor[m.lessonId]=allowed;save();el.value='';toast('导师反馈已保存到档案');}catch(e){toast('反馈格式有误：'+e.message)}}
async function importFile(file){if(!file)return;try{let obj=JSON.parse(await file.text());if(obj.schema!==1||!obj.quizzes||!obj.deep||!obj.reviews||!obj.coding)throw Error('不是支持的学习档案格式');if(!confirm('导入将替换当前学习数据。请确认已先导出备份，是否继续？'))return;data={...baseState(),...obj,settings:{...baseState().settings,...obj.settings,runnerToken:''}};save();render();toast('学习档案已恢复');}catch(e){toast('导入失败：'+e.message)}}
function handleInput(e){let t=e.target;if(t.id==='code-input'){let id=t.dataset.codeId,c=runStatus(id);if(c.code!==t.value){c.code=t.value;if(c.runner){c.runner={...c.runner,verified:false,output:'之前的验证结果已失效：代码已修改',environment:'编辑后待重新验证',at:time()}}save();}let gutter=document.getElementById('line-gutter');if(gutter)gutter.innerHTML=Array.from({length:Math.max(8,t.value.split('\n').length)},(_,i)=>i+1).join('<br>');}else if(t.dataset.interviewId){let id=t.dataset.interviewId;data.interview=data.interview||{};let rec=data.interview[id]||(data.interview[id]={draft:'',history:[]});rec.draft=t.value;save();}else if(t.dataset.deepLesson){let d=data.deep[t.dataset.deepLesson]||(data.deep[t.dataset.deepLesson]={answers:{}});d.answers[t.dataset.deepField]=t.value;save();}else if(t.dataset.proofId){runStatus(t.dataset.proofId).evidence=t.value;save();}else if(t.id==='runner-token'){data.settings.runnerToken=t.value;save();}else if(t.id?.startsWith('review-response-')){let id=t.id.slice('review-response-'.length);if(data.reviews[id]){data.reviews[id].draft=t.value;save();}}}
function handleKey(e){if(e.target.id==='code-input'&&e.key==='Tab'){e.preventDefault();let t=e.target,s=t.selectionStart,x=t.selectionEnd;t.value=t.value.slice(0,s)+'    '+t.value.slice(x);t.selectionStart=t.selectionEnd=s+4;handleInput({target:t})}}
window.addEventListener('hashchange',()=>{if(window.innerWidth<=800)sidebarExpanded=false;render();window.scrollTo(0,0)});document.addEventListener('click',handleClick);document.addEventListener('input',handleInput);document.addEventListener('keydown',handleKey);document.addEventListener('change',e=>{if(e.target.id==='backup-file')importFile(e.target.files?.[0]);if(e.target.dataset.reviewReason){let r=data.reviews[e.target.dataset.reviewReason];if(r){r.wrongReason=e.target.value;save();}}});document.addEventListener('click',e=>{let a=e.target.closest('[data-anchor]');if(a){e.preventDefault();document.getElementById(a.dataset.anchor)?.scrollIntoView({behavior:'smooth',block:'start'});}});
render();
})();
